using System;
using System.Linq;
using System.Reflection;
using XanaduYonder.Core.AgeOfWar;

internal static class Program
{
    private static int _passed, _failed;
    private static readonly BindingFlags Fields = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
    private static IAgeOfWarBattle New(int difficulty = 1, uint seed = 1)
    {
        var type = typeof(IAgeOfWarBattle).Assembly.GetType("XanaduYonder.Core.AgeOfWar.One.AgeOfWarOneBattle");
        Check(type != null, "The native first-edition simulation is missing");
        return (IAgeOfWarBattle)Activator.CreateInstance(type, difficulty, seed);
    }
    private static void Check(bool condition, string message) { if (!condition) throw new Exception(message); }
    private static void Equal(double expected, double actual, string message) { Check(Math.Abs(expected - actual) < 0.000001, message + ": expected " + expected + ", actual " + actual); }
    private static void Run(string name, Action body) { try { body(); ++_passed; Console.WriteLine("PASS " + name); } catch (Exception e) { ++_failed; Console.WriteLine("FAIL " + name + ": " + e.GetBaseException().Message); } }
    private static void Set(object target, string name, object value) { var f = target.GetType().GetField(name, Fields); Check(f != null, "Scenario field missing: " + name); f.SetValue(target, value); }
    private static object Get(object target, string name) { return target.GetType().GetField(name, Fields).GetValue(target); }
    private static object Invoke(object target, string method, params object[] args) { return target.GetType().GetMethod(method, Fields).Invoke(target, args); }
    private static void Ticks(IAgeOfWarBattle battle, int n) { for (int i = 0; i < n; ++i) battle.Tick(); }
    private static bool Do(IAgeOfWarBattle battle, AgeOfWarAction action, int id = 0, int slot = 0) { return battle.Execute(new AgeOfWarCommand(action, id, slot)); }
    private static object Spawn(IAgeOfWarBattle battle, int id, int side, double x) { var unit = Invoke(battle, "Spawn", id, side); Invoke(battle,"InitializeActor",unit); Set(unit, "X", x); return unit; }
    private static object Projectile(IAgeOfWarBattle b,double x,double y,double rotation,double damage,string id,int side){var p=Invoke(b,"CreateProjectile",x,y,rotation,damage,id,side);Invoke(b,"InitializeProjectile",p);return p;}
    private static object Transition(bool fade)
    {
        var type=typeof(IAgeOfWarBattle).Assembly.GetType("XanaduYonder.Runtime.AgeOfWar.AgeOfWarTransitionState");
        Check(type!=null,"Source bitmap transition state is missing");
        return Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{700,400,fade},null);
    }
