        Run("source pause keeps training and recharge", () => { var b=New(); Do(b,AgeOfWarAction.Train,1); Do(b,AgeOfWarAction.Pause); Ticks(b,40); var f=b.Capture(); Check(f.Paused && f.SpecialReady,"paused charge"); Equal(1,f.Population,"paused training"); Equal(0,(int)Get(b,"_techTimer"),"AI frozen"); b.Tick();var x=b.Capture().Visuals.Single(v=>v.Clip=="unit/1").X; b.Tick(); Equal(x,b.Capture().Visuals.Single(v=>v.Clip=="unit/1").X,"unit frozen"); Check(!Do(b,AgeOfWarAction.Train,1),"hidden menu cannot train"); });
        Run("cumulative XP evolves and preserves queue and old turrets",()=>{var b=New();Do(b,AgeOfWarAction.BuyTurret,1,1);Do(b,AgeOfWarAction.Train,1);Set(b,"_experience",4000);Check(Do(b,AgeOfWarAction.Evolve),"evolve");var f=b.Capture();Equal(4000,f.Experience,"XP never spent");Equal(1100,f.PlayerHealth,"600 HP bonus");Equal(4,f.Units[0].Id,"new offers");Equal(1,f.TurretSlots[0].TurretId,"old turret preserved");Check(!Do(b,AgeOfWarAction.Train,1),"old offers unavailable");Ticks(b,40);Equal(1,b.Capture().Population,"old queue still trains");});
        Run("all five age catalogs and super soldier",()=>{var b=New();Set(b,"_experience",200000);for(int age=1;age<=5;age++){var f=b.Capture();Equal(age,f.Age,"age");Equal(age==5?4:3,f.Units.Length,"offers");Equal(3,f.Turrets.Length,"turrets");if(age<5)Check(Do(b,AgeOfWarAction.Evolve),"evolve");}Equal(4700,b.Capture().PlayerMaxHealth,"all bonuses");Equal(150000,b.Capture().Units[3].Cost,"super soldier");Check(!Do(b,AgeOfWarAction.Evolve),"max age");});
        Run("turret slot prices and sale rounding",()=>{var b=New();Set(b,"_gold",20000);Check(Do(b,AgeOfWarAction.BuyTurret,1,1),"build");Check(!Do(b,AgeOfWarAction.BuyTurret,1,1),"occupied");Check(!Do(b,AgeOfWarAction.BuyTurret,1,2),"unbought slot");Check(Do(b,AgeOfWarAction.SellTurret,0,1),"sell");Equal(19950,b.Capture().Gold,"half");foreach(int cost in new[]{1000,3000,7500}){Equal(cost,b.Capture().NextTurretSlotCost,"slot cost");Check(Do(b,AgeOfWarAction.BuyTurretSlot),"buy slot");}Check(!Do(b,AgeOfWarAction.BuyTurretSlot),"four limit");});
